// Optional: keeps old WordPress short links working (https://bact.cc/?p=123 and ?page_id=2).
// Only the home page ("/") invokes this function; every other URL is served as a plain static file.
// _idmap.json is generated by tools/wp_convert.py (post id -> permalink path).
import idmap from "./_idmap.json";

export async function onRequest({ request, next }) {
  const url = new URL(request.url);
  const id = url.searchParams.get("p") || url.searchParams.get("page_id");
  const path = id && idmap[id];
  if (path) {
    return Response.redirect(url.origin + encodeURI(path), 301);
  }
  return next();
}
